import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. STAGE BACKDROP (Engineered Gradient Surface - Prevent Flat Void)
  const backdropGeo = new PlaneGeometry(8, 6);
  const backdropMat = new MeshBasicNodeMaterial({ depthWrite: false });

  // Create beautiful vertical gradient using TSL
  const color1 = vec3(0.086, 0.086, 0.114); // #16161d (ink)
  const color2 = vec3(0.043, 0.043, 0.063); // #0b0b10 (surface)
  backdropMat.colorNode = mix(color2, color1, uv().y);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.5, -0.5);
  group.add(backdrop);

  // 2. SPRITE PLANE (Billboarding image accent)
  const aspect = 512 / 320; // 1.6
  const spriteGeo = new PlaneGeometry(2.4 * aspect, 2.4);
  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  // Load the floating accent texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      spriteMat.map = tex;
      // Map atlas coordinates (0, 0, 512, 320) from possible 512x512 texture
      spriteMat.uvNode = uv().mul(vec2(1.0, 0.625)).add(vec2(0.0, 0.375));
      spriteMat.needsUpdate = true;
    });
  }

  const spriteMesh = new Mesh(spriteGeo, spriteMat);
  spriteMesh.position.set(0, 0, 0.05);
  group.add(spriteMesh);

  // Billboarding effect
  const activeCameraPosition = new Vector3();
  spriteMesh.onBeforeRender = (renderer, scene, camera) => {
    activeCameraPosition.setFromMatrixPosition(camera.matrixWorld);
    spriteMesh.lookAt(activeCameraPosition);
  };

  // 3. TYPOGRAPHY - "Journal"
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineText = items.find(item => item.role === 'headline')?.text ?? 'Journal';

  const textNode = ctx.fontAtlas.createText(headlineText, {
    fontSize: 0.62, // Display size
    color: colors.paper,
    align: 'center'
  });

  textNode.position.set(0, -0.8, 0.1);
  group.add(textNode);

  // Simple static entry animation
  gsap.fromTo(
    textNode.position,
    { y: -1.2, z: -0.2 },
    { y: -0.8, z: 0.1, duration: 1.2, ease: 'power4.out' }
  );

  gsap.fromTo(
    spriteMesh.position,
    { y: 0.4 },
    { y: 0, duration: 1.4, ease: 'power3.out' }
  );

  // Cleanup
  group.userData.cleanup = () => {
    backdropGeo.dispose();
    backdropMat.dispose();
    spriteGeo.dispose();
    spriteMat.dispose();
    gsap.killTweensOf(textNode.position);
    gsap.killTweensOf(spriteMesh.position);
  };

  return group;
}
